553	 * At runtime (ISR/SSR), uses internal API proxy for better caching and security.
554	 */
555	export async function fetchCategorizedEvents(
556	  maxEventsPerCategory?: number,
557	): Promise<CategorizedEvents> {
558	  const apiUrl = getApiUrl();
559	
560	  // During build phase, bypass internal proxy and call external API directly
561	  // This ensures SSG pages (homepage) can fetch data during next build
562	  if (isBuildPhase) {
563	    try {
564	      const data = await fetchCategorizedEventsExternal(maxEventsPerCategory);
565	      const validated = parseCategorizedEvents(data);
566	      if (!validated) {
567	        console.error("fetchCategorizedEvents: Build phase validation failed");
568	        return {};
569	      }
570	      return validated;
571	    } catch (e) {
572	      console.error(
573	        "fetchCategorizedEvents: Build phase external fetch failed:",
574	        e,
575	      );
576	      return {};
577	    }
578	  }
579	
580	  // Runtime: use direct external API call with caching
581	  // This avoids internal API proxy issues
582	  try {
583	    const params = new URLSearchParams();
584	    if (maxEventsPerCategory !== undefined) {
585	      params.append("maxEventsPerCategory", String(maxEventsPerCategory));
586	    }
587	
588	    const queryString = params.toString() ? `?${params.toString()}` : "";
589	    const finalUrl = `${apiUrl}/events/categorized${queryString}`;
590	
591	    const response = await fetchWithHmac(finalUrl, {
592	      next: { revalidate: 600, tags: ["events", "events:categorized"] },
593	      headers: {
594	        Accept: "application/json",
595	      },
596	    });
597	
598	    if (!response.ok) {
599	      const errorText = await response
600	        .text()
601	        .catch(() => "Unable to read error response");
602	      console.error(
603	        `fetchCategorizedEvents: HTTP error! status: ${response.status}, url: ${finalUrl}, error: ${errorText}`,
604	      );
605	      throw new Error(`HTTP error! status: ${response.status}`);
606	    }
607	    const data = await response.json();
608	    const validated = parseCategorizedEvents(data);
609	    if (!validated || Object.keys(validated).length === 0) {
610	      console.error("fetchCategorizedEvents: Runtime validation failed");
611	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
612	    }
613	    return validated;
614	  } catch {
615	    // If direct fetch fails, try external API helper as fallback (handles edge cases)
616	    try {
617	      const data = await fetchCategorizedEventsExternal(maxEventsPerCategory);
618	      const validated = parseCategorizedEvents(data);
619	      if (validated && Object.keys(validated).length > 0) {
620	        return validated;
621	      }
622	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
623	    } catch (fallbackError) {
624	      // Sanitize error logging to prevent information disclosure
625	      const errorMessage = getSanitizedErrorMessage(fallbackError);
626	      console.error(
627	        "fetchCategorizedEvents: Both direct and external API failed:",
628	        errorMessage,
629	      );
630	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
631	    }
632	  }
633	}
