694	/**
695	 * Insert ads at deterministic positions in the event list.
696	 * Uses fixed spacing instead of Math.random() to ensure the component tree
697	 * is identical across renders — required for cacheComponents (RSC resumption).
698	 */
699	function insertAdsDeterministic(
700	  events: EventSummaryResponseDTO[],
701	  ads: AdEvent[],
702	  spacing = 5,
703	  startFrom = 3,
704	): ListEvent[] {
705	  const result: ListEvent[] = [...events];
706	
707	  ads.forEach((ad, i) => {
708	    // Fixed position: startFrom + i * spacing, adjusted for prior insertions
709	    const index = startFrom + i * (spacing + 1);
710	    if (index <= result.length) {
711	      result.splice(index, 0, ad);
712	    }
713	  });
714	
715	  return result;
716	}
